import { useState, useEffect } from "react";
import api from "../../servicios/api";
import {
  crearEvaluacionPsico,
  actualizarEvaluacionPsico,
} from "../../servicios/evaluacionPsico";

// Escala del PDF
const ITEMS_COMUNICATIVAS = [
  { id: 1, descripcion: "Se comunica e interactúa con los demás de manera espontánea." },
  { id: 2, descripcion: "Se comunica e interactúa con los demás de manera guiada." },
  { id: 3, descripcion: "Participa en conversaciones con sus pares y/o adultos de forma espontánea." },
  { id: 4, descripcion: "La pronunciación, orden y estructura gramatical favorecen la comprensión del mensaje." },
  { id: 5, descripcion: "Utiliza oraciones completas en intervenciones orales/en lengua de señas." },
  { id: 6, descripcion: "Relata en forma secuenciada y clara experiencias personales." },
  { id: 7, descripcion: "Realiza y cumple instrucciones entregadas oralmente/en lengua de señas." },
  { id: 8, descripcion: "Ajusta su lenguaje a diversos contextos e interlocutores." },
  { id: 9, descripcion: "Su expresión oral/señada es coherente con su expresión facial/corporal." },
  { id: 10, descripcion: "Utiliza palabras, señas o conceptos especializados/rebuscados cuando corresponde." },
  { id: 11, descripcion: "Modula volumen y claridad de la voz/señalización según la situación." },
  { id: 12, descripcion: "Conoce y usa un vocabulario amplio." },
  { id: 13, descripcion: "Comunica sensaciones, emociones, necesidades e ideas a través del lenguaje." },
  { id: 14, descripcion: "Repite con frecuencia palabras/señas u oraciones (ecolalia)." },
];

function EvaluacionPsicoForm({ evaluacion, onSuccess }) {
  // Datos base
  const [formData, setFormData] = useState({
    estudiante: "",
    fecha: "",
    evaluador: "",
  });

  // Curso → Alumno
  const [cursoId, setCursoId] = useState("");
  const [cursos, setCursos] = useState([]);
  const [alumnos, setAlumnos] = useState([]);
  const [alumno, setAlumno] = useState(null);

  // IDENTIFICACIÓN / TRAYECTORIA / SITUACIÓN
  const [identificacion, setIdentificacion] = useState({
    observaciones_identificacion: "",
  });

  const [trayectoria, setTrayectoria] = useState({
    observaciones_trayectoria: "",
  });

  const [situacion, setSituacion] = useState({
    aspectos_destacados: "",
    observaciones_situacion: "",
  });

  // SUBDIMENSIÓN I
  const [valoresItems, setValoresItems] = useState(
    ITEMS_COMUNICATIVAS.reduce((acc, item) => ({ ...acc, [item.id]: 0 }), {})
  );

  const [fortalezaArea, setFortalezaArea] = useState("");
  const [debilidadArea, setDebilidadArea] = useState("");
  const [sintesisArea, setSintesisArea] = useState("");
  const [observacionesArea, setObservacionesArea] = useState("");

  // ===================================
  // Cargar cursos al iniciar
  // ===================================
  useEffect(() => {
    async function cargarCursos() {
      try {
        const res = await api.get("/cursos/");
        setCursos(res.data);
      } catch (err) {
        console.error("Error cargando cursos", err);
      }
    }
    cargarCursos();
  }, []);

  // ===================================
  // Si estamos editando: pre-cargar data
  // ===================================
  useEffect(() => {
    async function prefijar() {
      if (!evaluacion) return;

      setFormData({
        estudiante: evaluacion.estudiante || "",
        fecha: evaluacion.fecha || "",
        evaluador: evaluacion.evaluador || "",
      });

      // Cargar alumno y curso desde la evaluación (si viene el ID)
      if (evaluacion.estudiante) {
        try {
          const resEst = await api.get(`/estudiantes/${evaluacion.estudiante}/`);
          const est = resEst.data;
          setAlumno(est);

          if (est.curso?.id) {
            setCursoId(est.curso.id);
            await cargarAlumnosPorCurso(est.curso.id);
          }
        } catch (err) {
          console.error("Error cargando alumno de evaluación", err);
        }
      }
      // NOTA: Como guardamos todo en 'observaciones' como texto, no separamos de vuelta en estos campos.
    }
    prefijar();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [evaluacion]);

  // ===================================
  // Helpers para cargar alumnos
  // ===================================
  const cargarAlumnosPorCurso = async (idCurso) => {
    if (!idCurso) {
      setAlumnos([]);
      setAlumno(null);
      setFormData((prev) => ({ ...prev, estudiante: "" }));
      return;
    }
    try {
      const res = await api.get(`/estudiantes/?curso=${idCurso}`);
      setAlumnos(res.data);
    } catch (err) {
      console.error("Error cargando alumnos", err);
    }
  };

  const cargarAlumno = async (idEstudiante) => {
    if (!idEstudiante) {
      setAlumno(null);
      return;
    }
    try {
      const res = await api.get(`/estudiantes/${idEstudiante}/`);
      setAlumno(res.data);
    } catch (err) {
      console.error("Error cargando ficha del alumno", err);
    }
  };

  // ===================================
  // Handlers
  // ===================================
  const handleCursoChange = async (e) => {
    const id = e.target.value;
    setCursoId(id);
    await cargarAlumnosPorCurso(id);
  };

  const handleAlumnoChange = (e) => {
    const id = e.target.value;
    setFormData((prev) => ({ ...prev, estudiante: id }));
    cargarAlumno(id);
  };

  const handleChangeBase = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleChangeIdentificacion = (e) => {
    const { name, value } = e.target;
    setIdentificacion((prev) => ({ ...prev, [name]: value }));
  };

  const handleChangeTrayectoria = (e) => {
    const { name, value } = e.target;
    setTrayectoria((prev) => ({ ...prev, [name]: value }));
  };

  const handleChangeSituacion = (e) => {
    const { name, value } = e.target;
    setSituacion((prev) => ({ ...prev, [name]: value }));
  };

  const handleRadioChange = (itemId, valor) => {
    setValoresItems((prev) => ({ ...prev, [itemId]: valor }));
  };

  // ===================================
  // Submit
  // ===================================
  const handleSubmit = async (e) => {
    e.preventDefault();

    const textoObservacionesCompuesto = `
[IDENTIFICACIÓN DEL ESTUDIANTE]
${identificacion.observaciones_identificacion || "-"}

[TRAYECTORIA ESCOLAR]
${trayectoria.observaciones_trayectoria || "-"}

[SITUACIÓN ESCOLAR ACTUAL]
Aspectos destacados:
${situacion.aspectos_destacados || "-"}

Otras observaciones:
${situacion.observaciones_situacion || "-"}

[I. HABILIDADES COMUNICATIVAS]
${ITEMS_COMUNICATIVAS.map(
  (item) => ` ${item.id}. ${item.descripcion} => ${valoresItems[item.id]}`
).join("\n")}

Fortaleza: ${fortalezaArea || "-"}
Debilidad: ${debilidadArea || "-"}
Síntesis: ${sintesisArea || "-"}
Observaciones adicionales: ${observacionesArea || "-"}
    `.trim();

    const payload = {
      estudiante: formData.estudiante,
      fecha: formData.fecha,
      evaluador: formData.evaluador,
      observaciones: textoObservacionesCompuesto,
    };

    try {
      if (evaluacion?.id) {
        await actualizarEvaluacionPsico(evaluacion.id, payload);
      } else {
        await crearEvaluacionPsico(payload);
      }
      alert("✔ Evaluación guardada correctamente");
      onSuccess?.();
    } catch (err) {
      console.error(err);
      alert("❌ Error al guardar la evaluación");
    }
  };

  // ===================================
  // RENDER
  // ===================================
  return (
    <form onSubmit={handleSubmit} className="bg-light p-3 border rounded">

      {/* CURSO + ALUMNO */}
      <div className="row mb-3">
        <div className="col-md-6">
          <label className="form-label">Curso</label>
          <select
            className="form-select"
            value={cursoId}
            onChange={handleCursoChange}
          >
            <option value="">Seleccionar curso...</option>
            {cursos.map((c) => (
              <option key={c.id} value={c.id}>
                {c.nombre} {c.anio_escolar ? `(${c.anio_escolar})` : ""}
              </option>
            ))}
          </select>
        </div>

        <div className="col-md-6">
          <label className="form-label">Alumno</label>
          <select
            className="form-select"
            name="estudiante"
            value={formData.estudiante}
            onChange={handleAlumnoChange}
            disabled={!cursoId}
            required
          >
            <option value="">
              {cursoId ? "Seleccionar alumno..." : "Seleccione curso primero"}
            </option>
            {alumnos.map((a) => (
              <option key={a.id} value={a.id}>
                {a.nombres_apellidos} — {a.run || ""}
              </option>
            ))}
          </select>
        </div>
      </div>

      {/* FICHA DEL ALUMNO */}
      {alumno && (
        <div className="alert alert-secondary">
          <h5 className="mb-2">Ficha del estudiante</h5>
          <p><b>Nombre:</b> {alumno.nombres_apellidos}</p>
          <p><b>RUN:</b> {alumno.run || "—"}</p>
          <p><b>Curso:</b> {alumno.curso?.nombre || "—"}</p>
          <p><b>Género:</b> {alumno.genero || "—"}</p>
          <p><b>Fecha nacimiento:</b> {alumno.fecha_nacimiento || "—"}</p>
          <p><b>Apoderado:</b> {alumno.apoderado?.nombres_apellidos || "—"}</p>
        </div>
      )}

      {/* EVALUADOR + FECHA */}
      <div className="row mb-3 mt-3">
        <div className="col-md-6">
          <label className="form-label">Evaluador</label>
          <input
            className="form-control"
            name="evaluador"
            value={formData.evaluador}
            onChange={handleChangeBase}
            required
          />
        </div>
        <div className="col-md-6">
          <label className="form-label">Fecha</label>
          <input
            type="date"
            className="form-control"
            name="fecha"
            value={formData.fecha}
            onChange={handleChangeBase}
          />
        </div>
      </div>

      {/* IDENTIFICACIÓN */}
      <h5 className="mt-4">Identificación del estudiante</h5>
      <div className="mb-3">
        <label className="form-label">Observaciones de identificación</label>
        <textarea
          className="form-control"
          rows={2}
          name="observaciones_identificacion"
          value={identificacion.observaciones_identificacion}
          onChange={handleChangeIdentificacion}
          placeholder="Lengua materna, lengua de uso, vía de comunicación, escolaridad alcanzada, etc."
        />
      </div>

      {/* TRAYECTORIA */}
      <h5 className="mt-4">Trayectoria escolar</h5>
      <div className="mb-3">
        <label className="form-label">Observaciones de trayectoria</label>
        <textarea
          className="form-control"
          rows={2}
          name="observaciones_trayectoria"
          value={trayectoria.observaciones_trayectoria}
          onChange={handleChangeTrayectoria}
          placeholder="Edad ingreso al sistema, jardines infantiles, repitencias, cambios de colegio y motivos, etc."
        />
      </div>

      {/* SITUACIÓN ACTUAL */}
      <h5 className="mt-4">Situación escolar actual</h5>
      <div className="mb-3">
        <label className="form-label">
          Aspectos destacados en su historia educativa
          <span className="text-muted">
            {" "}
            (conducta, rendimiento, participación, relaciones sociales…)
          </span>
        </label>
        <textarea
          className="form-control"
          rows={2}
          name="aspectos_destacados"
          value={situacion.aspectos_destacados}
          onChange={handleChangeSituacion}
        />
      </div>
      <div className="mb-3">
        <label className="form-label">Otras observaciones de situación escolar</label>
        <textarea
          className="form-control"
          rows={2}
          name="observaciones_situacion"
          value={situacion.observaciones_situacion}
          onChange={handleChangeSituacion}
        />
      </div>

      {/* SUBDIMENSIÓN I */}
      <h5 className="mt-4">I. Habilidades comunicativas</h5>
      <p className="text-muted">
        S=Siempre (1), G=Generalmente (2), O=Ocasionalmente (3),
        N=Nunca (4), N/O=No observado (0).
      </p>

      <table className="table table-bordered align-middle">
        <thead className="table-secondary text-center">
          <tr>
            <th style={{ width: "60%" }}>Ítem</th>
            <th>S<br />1</th>
            <th>G<br />2</th>
            <th>O<br />3</th>
            <th>N<br />4</th>
            <th>N/O<br />0</th>
          </tr>
        </thead>
        <tbody>
          {ITEMS_COMUNICATIVAS.map((item) => (
            <tr key={item.id}>
              <td>{item.descripcion}</td>
              {[1, 2, 3, 4, 0].map((valor) => (
                <td className="text-center" key={valor}>
                  <input
                    type="radio"
                    name={`item-${item.id}`}
                    checked={valoresItems[item.id] === valor}
                    onChange={() => handleRadioChange(item.id, valor)}
                  />
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>

      {/* FORTALEZA / DEBILIDAD / SÍNTESIS / OBSERVACIONES ÁREA */}
      <div className="mb-3">
        <label className="form-label">
          Mayor <strong>fortaleza</strong> en esta área
        </label>
        <textarea
          className="form-control"
          rows={2}
          value={fortalezaArea}
          onChange={(e) => setFortalezaArea(e.target.value)}
        />
      </div>
      <div className="mb-3">
        <label className="form-label">
          Mayor <strong>debilidad</strong> en esta área
        </label>
        <textarea
          className="form-control"
          rows={2}
          value={debilidadArea}
          onChange={(e) => setDebilidadArea(e.target.value)}
        />
      </div>
      <div className="mb-3">
        <label className="form-label">
          <strong>Síntesis</strong> del desempeño general
        </label>
        <textarea
          className="form-control"
          rows={2}
          value={sintesisArea}
          onChange={(e) => setSintesisArea(e.target.value)}
        />
      </div>
      <div className="mb-3">
        <label className="form-label">
          Observaciones adicionales del área
        </label>
        <textarea
          className="form-control"
          rows={2}
          value={observacionesArea}
          onChange={(e) => setObservacionesArea(e.target.value)}
        />
      </div>

      <button type="submit" className="btn btn-success w-100 mt-3">
        {evaluacion ? "Actualizar evaluación" : "Crear evaluación"}
      </button>
    </form>
  );
}

export default EvaluacionPsicoForm;
